const root=load("retestEvidence"),work=load("work"),data=load("planData"),corr=load("brighterCorrelation");
function sort(x){return Array.isArray(x)?x.map(sort):x&&typeof x==="object"?Object.fromEntries(Object.keys(x).sort().map(k=>[k,sort(x[k])])):x;}
const eq=(a,b)=>JSON.stringify(sort(a))===JSON.stringify(sort(b));
const parse=r=>{if(r.isError)throw Error(r.content[0].text);return JSON.parse(r.content[0].text)};
async function save(path,value){await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"/"+path+"\n"+JSON.stringify(value,null,2).split("\n").map(x=>"+"+x).join("\n")+"\n*** End Patch");}
async function call(tool,args,path){const raw=await tools[tool](args);await save(path,raw);return parse(raw);}
async function offline(op,arg){let r=await tools.exec_command({cmd:"$env:PYTHONPATH='"+work+"/build/validation/hmd-python-deps'; python '"+root+"/direct-offline.py' '"+root+"' '"+work+"' "+op+" "+arg,max_output_tokens:3000});let out=r.output;while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:3000});out+=r.output;}if(r.exit_code!==0)throw Error(out);return JSON.parse(out);}
function editable(value){const v=JSON.parse(JSON.stringify(value));for(const name of ["upscaled_center","final_ldr_pre_ui"]){const z=v.experiments[name];v.experiments[name]={domain:z.domain,transform:z.transform,exposureMultiplier:z.exposureMultiplier,exposureSource:z.exposureSource};}return v;}
store("brighterCaptured",[]);store("campaignFailure",null);
for(const ordinal of data.selectedOrdinals){
 const prefix="steps/"+String(ordinal).padStart(3,"0")+"/",step=data.schedule[ordinal-1],candidate=data.plan.candidateMapping[step.candidateId],desired=data.candidateConfigurations[step.candidateId];
 try{
  let status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"before.json");
  if(status.producer.buildId!=="4385d3607500f6dd1006d3c90bd9a15b89eb193ab3795b4300b9155ec37c38e9")throw Error("producer changed");
  if(!eq(status.neuralRendering.requestedConfiguration,load("lastOwnedConfiguration")))throw Error("configuration ownership changed");
  let nr=status.neuralRendering;
  if(!eq(editable(nr.requestedConfiguration.color),desired)){
   const color=await call("mcp__devbench_vr__communityshaders_nr_color",{action:"configure",expectedRevision:load("ownedRevision"),...desired},prefix+"configure-colour.json");
   if(!color.ok||!eq(editable({settings:color.settings,experiments:color.experiments}),desired))throw Error("colour acknowledgement differs");
   store("ownedRevision",color.revision);
   status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"after-colour.json");nr=status.neuralRendering;store("lastOwnedConfiguration",nr.requestedConfiguration);
  }
  const enabled=(candidate.sourceCondition||candidate.condition)!=="nr_off";
  if(nr.requestedConfiguration.upscaling.neuralRenderingEnabled!==enabled){
   const result=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_configure",enabled,expectedConfigurationFingerprint:nr.requestedConfigurationFingerprint},prefix+"configure-master.json");
   if(!result.ok)throw Error("NR transition failed");
   store("lastOwnedConfiguration",result.neuralRendering.requestedConfiguration);
   status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"after-master.json");nr=status.neuralRendering;
  }
  store("lastOwnedConfiguration",nr.requestedConfiguration);
  await save(prefix+"applied.json",{content:[{type:"text",text:JSON.stringify(status)}],isError:false});
  let expected=await offline("expected",String(ordinal));
  if(!expected.ok){
   await save(prefix+"initial-applied-errors.json",expected);
   for(let retry=1;retry<=3&&!expected.ok;retry++){
    status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"applied-retry-"+retry+".json");
    await save(prefix+"applied.json",{content:[{type:"text",text:JSON.stringify(status)}],isError:false});
    expected=await offline("expected",String(ordinal));
   }
  }
  if(!expected.ok)throw Error("NR application not evidenced: "+JSON.stringify(expected.errors));
  await call("mcp__devbench_vr__menu",{action:"close",name:"Journal Menu"},prefix+"close-journal.json");
  const capture={...load("captureDescriptor"),destination:{policy:"absolute",directory:root+"/"+prefix+"frames",baseName:"frame",overwrite:"never"},tags:{captureInteractionSessionId:corr}};
  const started=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"sequence_start",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-"+ordinal+"-start",sequence:{frameCount:12,useSettings:false,schedule:{basis:"wall_clock",intervalMs:500,startDelayMs:0,pausePolicy:"hold"},backpressure:{policy:"skip",maximumConsecutiveSkips:20},failurePolicy:"continue",capture,packaging:{frameManifest:true,previewVideo:{requested:false,required:false,framesPerSecond:2}}}},prefix+"capture-start.json");
  if(!started.ok)throw Error("sequence rejected");
  const id=started.result.requestId;store("activeScreenshotRequest",id);await new Promise(r=>setTimeout(r,6300));
  let got;
  for(let poll=0;poll<5;poll++){got=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"request_get",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-"+ordinal+"-get-"+poll,requestId:id},prefix+"capture-get-"+poll+".json");if(["completed","completed_with_warnings","failed","failed_partial","stopped","cancelled","rejected"].includes(got.result.state))break;}
  const terminal=got.result;if(!["completed","completed_with_warnings"].includes(terminal.state))throw Error("sequence terminal "+terminal.state);
  store("activeScreenshotRequest",null);const manifest=terminal.artifacts.find(a=>a.path===terminal.manifest.finalPath);if(!manifest)throw Error("manifest missing");
  const stamps=await offline("stamps","'"+manifest.path+"'");
  const diagnostics=await call("mcp__devbench_vr__communityshaders_nr_color",{action:"capture_diagnostics",stamps:stamps.stamps},prefix+"exposure-raw.json");
  await save(prefix+"capture-diagnostics.json",diagnostics);
  const entry={scheduleOrdinal:ordinal,expected:expected.expected,captureSessionDirectory:root+"/"+prefix,captureSessionId:corr,manifest,terminalReceipt:terminal,captureDiagnostics:diagnostics,transport:"direct_mcp"};
  await save(prefix+"entry-core.json",entry);store("brighterCaptured",[...load("brighterCaptured"),entry]);
  text({captured:load("brighterCaptured").length,total:data.selectedOrdinals.length,scheduleOrdinal:ordinal,pairs:terminal.counts.written,role:step.role});
  await yield_control();
 }catch(e){const failure={ordinal,error:String(e)};store("campaignFailure",failure);await save(prefix+"failure.json",failure);text(failure);break;}
}
if(load("activeScreenshotRequest")){
 const stopped=await tools.mcp__devbench_vr__communityshaders_screenshot({action:"sequence_stop",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-failure-stop",requestId:load("activeScreenshotRequest")});await save("failure-sequence-stop.json",stopped);
}
const recording=await call("mcp__devbench_vr__record",{action:"stop",expectedCorrelationId:corr},"campaign-record-stop.json");store("activeRecordCorrelation",null);store("brighterRecording",recording);

